import type { Ref } from 'vue'
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'

/**
 * useInView — reactive IntersectionObserver wrapper (generalises the observer
 * behind the `v-reveal` directive in `directives/reveal.ts`).
 *
 * Observers are shared per unique `(rootMargin, threshold)` signature so a page
 * full of demos attaches only a handful of `IntersectionObserver`s rather than
 * one per element. By default it fires once and unobserves on first intersect
 * (the scroll-reveal pattern). When `IntersectionObserver` is unavailable
 * (SSR / very old browsers) the element is treated as in view immediately so
 * content is never blocked.
 */

/** Options accepted by {@link useInView}. */
export interface UseInViewOptions {
  /** Margin around the root, e.g. `'0px 0px -10% 0px'`. */
  rootMargin?: string
  /** Visibility ratio(s) that trigger a callback. */
  threshold?: number | number[]
  /** Reveal once then stop observing (default `true`). */
  once?: boolean
}

/** Per-element callback registry, keyed weakly so detached nodes are collectable. */
const callbacks = new WeakMap<Element, (isInView: boolean) => void>()

/** Shared observers keyed by their serialized option signature. */
const observers = new Map<string, IntersectionObserver>()

function optionsKey(rootMargin: string, threshold: number | number[]): string {
  return `${rootMargin}|${JSON.stringify(threshold)}`
}

function getObserver(rootMargin: string, threshold: number | number[]): IntersectionObserver | null {
  if (typeof window === 'undefined' || typeof IntersectionObserver === 'undefined')
    return null

  const key = optionsKey(rootMargin, threshold)
  let observer = observers.get(key)
  if (!observer) {
    observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          callbacks.get(entry.target)?.(entry.isIntersecting)
        }
      },
      { rootMargin, threshold },
    )
    observers.set(key, observer)
  }
  return observer
}

/**
 * Observe `elRef`'s element and report whether it is in view.
 *
 * @param elRef - template ref to the element to observe.
 * @param options - see {@link UseInViewOptions}.
 * @returns a reactive `isInView` ref.
 */
export function useInView(
  elRef: Ref<HTMLElement | null | undefined>,
  options: UseInViewOptions = {},
): Ref<boolean> {
  const { rootMargin = '0px 0px -10% 0px', threshold = 0.05, once = true } = options
  const isInView = ref(false)

  let observed: Element | null = null
  let observer: IntersectionObserver | null = null

  function unobserve(): void {
    if (observed) {
      observer?.unobserve(observed)
      callbacks.delete(observed)
      observed = null
    }
  }

  function observe(el: HTMLElement): void {
    unobserve()
    observer = getObserver(rootMargin, threshold)
    if (!observer) {
      // No IntersectionObserver → treat as in view immediately.
      isInView.value = true
      return
    }
    callbacks.set(el, (inView) => {
      isInView.value = inView
      if (inView && once)
        unobserve()
    })
    observer.observe(el)
    observed = el
  }

  onMounted(() => {
    if (elRef.value)
      observe(elRef.value)
  })

  watch(elRef, (el) => {
    if (el)
      observe(el)
    else unobserve()
  })

  onBeforeUnmount(unobserve)

  return isInView
}

import type { InjectionKey, Ref } from 'vue'
import { computed, inject, provide, ref } from 'vue'

/**
 * useReducedMotion — central reduced-motion preference for the animations gallery.
 *
 * Resolves to `true` when EITHER the OS exposes
 * `(prefers-reduced-motion: reduce)` OR a page-level override has been turned on
 * via {@link provideMotionPreference}. This lets the gallery honour the user's
 * system setting while also letting `AnimationsPage` force "reduced" live for the
 * demo toggle. SSR-safe (guards `window`/`matchMedia`) and reactive to OS changes.
 */

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)'

/** Injection key carrying the page-level reduced-motion override flag. */
const MotionOverrideKey: InjectionKey<Ref<boolean>> = Symbol('dz-motion-override')

/**
 * Module-singleton ref tracking the OS `prefers-reduced-motion` setting. One
 * `matchMedia` listener is attached for the whole app lifetime so every consumer
 * shares a single source of truth.
 */
let osPreference: Ref<boolean> | null = null

function useOsReducedMotion(): Ref<boolean> {
  if (osPreference)
    return osPreference

  const state = ref(false)
  if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
    const mql = window.matchMedia(REDUCED_MOTION_QUERY)
    state.value = mql.matches
    mql.addEventListener('change', (event: MediaQueryListEvent) => {
      state.value = event.matches
    })
  }

  osPreference = state
  return state
}

/**
 * provideMotionPreference — install the page-level override that callers of
 * {@link useReducedMotion} downstream will read.
 *
 * Returns the writable override ref so the provider (e.g. `AnimationsPage`) can
 * bind it to a "Reduce motion" toggle. When `true`, every descendant resolves
 * reduced motion regardless of the OS setting.
 *
 * @param initial - initial override value (default `false`).
 */
export function provideMotionPreference(initial = false): Ref<boolean> {
  const override = ref(initial)
  provide(MotionOverrideKey, override)
  return override
}

/**
 * useReducedMotion — reactive boolean, `true` when motion should be reduced.
 *
 * Combines the OS setting with any page-level override installed by
 * {@link provideMotionPreference}. Read-only; mutate the override via the ref
 * returned from `provideMotionPreference`.
 */
export function useReducedMotion(): Readonly<Ref<boolean>> {
  const os = useOsReducedMotion()
  const override = inject(MotionOverrideKey, null)
  return computed(() => os.value || (override?.value ?? false))
}
